gesamthypothekenvermaechtnis_drittleistungsmodell <- function(gesicherter_schuldbetrag=NULL, interne_berichtigungspflicht=NULL, vom_dritten_erlangbarer_betrag=NULL, grundstuecke=NULL, vermachtes_grundstueck_id=NULL, quotierungsbasis=NULL, drittleistungsreihenfolge=NULL, methodennachweis=NULL) {
 schuld <- .geld(gesicherter_schuldbetrag);innen <- .geld(interne_berichtigungspflicht);dritt <- .geld(vom_dritten_erlangbarer_betrag);.text(methodennachweis,'methodennachweis');.auswahl(quotierungsbasis,'quotierungsbasis',c('gesicherte_schuld','interne_berichtigungspflicht'));.auswahl(drittleistungsreihenfolge,'drittleistungsreihenfolge',c('vor_wertquote','nur_innenrestgrenze'))
 if(.vergleichen(innen,schuld)>0||.vergleichen(dritt,innen)>0) .fehler('innenpflicht_und_drittbetrag','Innenpflicht h\u00f6chstens Schuld, Drittbetrag h\u00f6chstens Innenpflicht.')
 kern <- gesamthypothekenvermaechtnis_befriedigungsbetrag(.bruchteile(schuld),grundstuecke,vermachtes_grundstueck_id,TRUE,TRUE,FALSE,TRUE,FALSE,methodennachweis)$wert
 if(is.null(kern$verteilungsquote)) .fehler('grundstuecke','Positive Wertsumme zur Quotierung erforderlich.')
 quote <- .geld(kern$verteilungsquote);deckung <- .bruch(0)
 for(p in kern$bereinigte_grundstueckswerte) if(p$grundstueck_id==vermachtes_grundstueck_id) deckung <- .geld(p$bereinigter_wert)
 rest <- .subtrahieren(innen,dritt);basis <- if(quotierungsbasis=='gesicherte_schuld')schuld else innen
 if(drittleistungsreihenfolge=='vor_wertquote') basis <- .subtrahieren(basis,dritt)
 anteil <- .multiplizieren(basis,quote);betrag <- anteil
 for(x in list(rest,deckung)) if(.vergleichen(x,betrag)<0) betrag <- x
 wert <- list(wertquote=.bruchteile(quote),nettodeckung=.bruchteile(deckung),verbleibende_innenpflicht=.bruchteile(rest),basis_vor_quotierung=.bruchteile(basis),quotierter_betrag=.bruchteile(anteil),befriedigungsbetrag=.bruchteile(betrag))
 eingaben <- list(gesicherter_schuldbetrag=gesicherter_schuldbetrag, interne_berichtigungspflicht=interne_berichtigungspflicht, vom_dritten_erlangbarer_betrag=vom_dritten_erlangbarer_betrag, grundstuecke=grundstuecke, vermachtes_grundstueck_id=vermachtes_grundstueck_id, quotierungsbasis=quotierungsbasis, drittleistungsreihenfolge=drittleistungsreihenfolge, methodennachweis=methodennachweis)
 ergebnis <- .ergebnis(wert,"EUR_und_Quote","BGB_GESAMTHYPOTHEKENVERMAECHTNIS_DRITTLEISTUNGSMODELL",eingaben,list(list(operation="Gew\u00e4hlte Schuld-/Innenpflichtbasis und Drittleistungsreihenfolge mit vorhandener Grundst\u00fcckswertquote verbinden; Betrag auf Innenrest und Nettodeckung begrenzen.")),eingaben)
 ergebnis$hinweise <- list("Bedingte2166II/2167-Rechnung: bestehender Grundst\u00fccksquotenkern liefert Nettodeckung und Wertquote. Innenrest=interneBerichtigungspflicht-erlangbareDrittberichtigung. Ausdr\u00fccklich gew\u00e4hlte Quotierungsbasis ist Gesamtschuld oder internePflicht. Bei vor_wertquote Drittbetrag von dieser Basis vor Quotierung abziehen; bei nur_innenrestgrenze bleibt die Quote ungek\u00fcrzt und Drittberichtigung wirkt nur durch den Innenrestdeckel. Betrag=min(quotierterBasis,Innenrest,Nettodeckung). Vier arithmetische Kombinationen sind keine vier als rechtlich zul\u00e4ssig best\u00e4tigten Alternativen: keine Standardwahl, zwingende fallbezogene rechtliche Begr\u00fcndung. Modellwahl und ihre allgemeine rechtliche Geltung bleiben getrennt von getesteter Arithmetik.2168IIrechtliche Verweisung nur im qualifizierten Nachlassgruppenfall; Fremdgrundst\u00fcckswerte nicht aufnehmen.2168Iohne2166II-Verweisung ist kein Anwendungsfall.2168aSchiffshypotheken nur bei qualifizierter entsprechender Anwendung.")
 ergebnis
}
